import logging

from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.schemas.FDSW23C.time import NTPSettings
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Time():
    def __init__(self, client):
        self._client = client

    def get_ntp_parameters(self, timeout=10):
        ntp = self._client.send(
            method='config.time.fetch',
            timeout=timeout,
            parameters={})
        if ntp.status is False:
            error_msg = "Get ntp parameters information is not available {}, error {}"
            raise OperationFailure(error_msg)

        get_ntp_parameters = NTPSettings.from_object_dict(data=ntp.data)
        return get_ntp_parameters.to_dict()

    def set_ntp_parameters(self, timeout, **kwargs):
        parameter_mapping = {
            'ntp_server_domain': 'ntpServerDomain',
            'ntp_servers': 'ntpServers',
            'time_zone': 'timeZone'
        }

        parameters = {
            param_name: kwargs[key]
            for key, param_name in parameter_mapping.items()
            if key in kwargs and key != 'ntp_servers'
        }
        if 'ntp_servers' in kwargs:
            parameters['ntpServers'] = [{'host': ip} for ip in kwargs['ntp_servers']]

        if parameters:  # Only send the request if there are parameters to update
            self._client.send(
                method='config.time.update',
                timeout=timeout,
                parameters=parameters
            )
